import random, statistics

def make_shift(seed=18,n=2000):
    rng=random.Random(seed); out=[]
    for t in range(n):
        out.append(rng.gauss(11.2,1.0) if 800<=t<1400 else rng.gauss(10.0,1.0))
    return out

def make_spike(seed=18,n=2000):
    rng=random.Random(seed); s=[rng.gauss(0,1) for _ in range(n)]; s[500]+=6; return s

def cusum_adaptive(x, mu0, sigma, k=0.5, h=5.0, lam=0.05, clamp=None):
    su=sd_=0.0; mu=mu0; alarms=[]
    for t,v in enumerate(x):
        z=(v-mu)/sigma
        if clamp: z=max(-clamp,min(clamp,z))
        su=max(0.0,su+z-k); sd_=max(0.0,sd_-z-k)
        if su>h:
            alarms.append((t,'up')); su=sd_=0.0; mu=v
        elif sd_>h:
            alarms.append((t,'down')); su=sd_=0.0; mu=v
        else:
            mu+=lam*(v-mu)
    return alarms

for lam in (0.02,0.05,0.1):
